package dao;
import model.*;import java.sql.*;import java.time.*;import java.util.*;
public class ThongKeDAO {
 private final MonanDAO monDAO=new MonanDAO();
 private HoaDon readInvoice(ResultSet r)throws SQLException{return new HoaDon(r.getInt("id"),r.getString("customer_name"),r.getString("table_name"),r.getTimestamp("issued_at").toLocalDateTime());}
 public HoaDon timHoaDon(int id){try(Connection c=Database.connect();PreparedStatement s=c.prepareStatement("SELECT id,customer_name,table_name,issued_at FROM invoice WHERE id=? AND status='PAID'")){s.setInt(1,id);try(ResultSet r=s.executeQuery()){return r.next()?readInvoice(r):null;}}catch(SQLException e){throw new IllegalStateException("Lỗi tải hóa đơn",e);}}
 public List<ChiTietHoaDon> chiTietHoaDon(int id){List<ChiTietHoaDon> ds=new ArrayList<>();try(Connection c=Database.connect();PreparedStatement s=c.prepareStatement("SELECT invoice_id,food_id,quantity,unit_price FROM invoice_detail WHERE invoice_id=? ORDER BY id")){s.setInt(1,id);try(ResultSet r=s.executeQuery()){while(r.next())ds.add(new ChiTietHoaDon(r.getInt(1),r.getInt(2),r.getInt(3),r.getLong(4)));}}catch(SQLException e){throw new IllegalStateException("Lỗi tải chi tiết hóa đơn",e);}return ds;}
 public List<HoaDon> lanGoiMon(int monId,LocalDate batDau,LocalDate ketThuc){List<HoaDon> ds=new ArrayList<>();String sql="SELECT DISTINCT i.id,i.customer_name,i.table_name,i.issued_at FROM invoice i JOIN invoice_detail d ON d.invoice_id=i.id WHERE d.food_id=? AND i.status='PAID' AND i.issued_at>=? AND i.issued_at<? ORDER BY i.issued_at DESC,i.id DESC";
 try(Connection c=Database.connect();PreparedStatement s=c.prepareStatement(sql)){s.setInt(1,monId);s.setTimestamp(2,Timestamp.valueOf(batDau.atStartOfDay()));s.setTimestamp(3,Timestamp.valueOf(ketThuc.plusDays(1).atStartOfDay()));try(ResultSet r=s.executeQuery()){while(r.next())ds.add(readInvoice(r));}}catch(SQLException e){throw new IllegalStateException("Lỗi tải lịch sử gọi món",e);}return ds;}
 public List<ThongKeMonAn> thongKe(LocalDate batDau,LocalDate ketThuc){List<ThongKeMonAn> ds=new ArrayList<>();String sql="SELECT f.id,f.name,f.category,f.price,f.serving,f.description,COUNT(DISTINCT d.invoice_id) call_count,SUM(d.quantity) qty,SUM(d.quantity*d.unit_price) revenue FROM food f JOIN invoice_detail d ON d.food_id=f.id JOIN invoice i ON i.id=d.invoice_id WHERE i.status='PAID' AND i.issued_at>=? AND i.issued_at<? GROUP BY f.id,f.name,f.category,f.price,f.serving,f.description ORDER BY revenue DESC,f.name";
 try(Connection c=Database.connect();PreparedStatement s=c.prepareStatement(sql)){s.setTimestamp(1,Timestamp.valueOf(batDau.atStartOfDay()));s.setTimestamp(2,Timestamp.valueOf(ketThuc.plusDays(1).atStartOfDay()));try(ResultSet r=s.executeQuery()){while(r.next()){Monan f=new Monan(r.getInt("id"),r.getString("name"),r.getString("category"),r.getLong("price"),r.getString("serving"),r.getString("description"));ds.add(new ThongKeMonAn(f,r.getInt("call_count"),r.getInt("qty"),r.getLong("revenue")));}}}catch(SQLException e){throw new IllegalStateException("Lỗi thống kê doanh thu",e);}return ds;}
 public long tongTien(int hoaDonId){long sum=0;for(ChiTietHoaDon d:chiTietHoaDon(hoaDonId))sum+=d.getThanhTien();return sum;}
 public Monan timMon(int id){return monDAO.timTheoId(id);}
}
